mapper.select:
select b.*,k.name bookName,k.cover bookCover,u.name userName,u.avatar userAvatar
from borrow b left join book k on b.book_id=k.id left join `user` u on b.user_id=u.id

  and b.user_id=#{userId}
  and b.status=#{status}
  and k.name like concat('%',#{bookName},'%')

order by b.borrow_time desc
